/* Feature grid */

.bm-feature-71-grid-ul {
  --line-thickness:1px;
  --line-color: var(--base-ultra-light);
  --line-offset:0px;
  overflow: hidden;
}


/* Psuedo Elmenets */

.bm-feature-71-grid-ul > .bm-feature-71-card::before,
.bm-feature-71-grid-ul > .bm-feature-71-card::after {
  content: '';
  position: absolute;
  background-color: var(--line-color);
}

/* Row Lines */

.bm-feature-71-grid-ul > .bm-feature-71-card::after {
  inline-size: 100vw;
  block-size: var(--line-thickness);
  inset-block-start: calc(var(--line-offset) * -1);
  inset-inline-start:0;
}

/* Column Lines */

.bm-feature-71-grid-ul > .bm-feature-71-card::before {
  inline-size: var(--line-thickness);
  block-size: 100vh;
  inset-block-start: 0;
  inset-inline-start: calc(var(--line-offset) * -1);
}


@media (min-width:991px) {

    .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(1)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(4)::before{
      inset-inline-start: calc(1em * -1);
    }

  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(1)::after,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(2)::after,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(3)::after{
      inset-block-start: calc(1em * -1);
    }

  }

    .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(1)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(4)::before{
      inset-inline-start: calc(1em * -1);
    }

  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(1)::after,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(2)::after,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(3)::after{
      inset-block-start: calc(1em * -1);
    }

@media (max-width:991px) {
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(3)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(5)::before{
      inset-inline-start: calc(1em * -1);
    }

 .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(4)::before{
      inset-inline-start: calc(var(--line-offset) * -1);
    }

  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(3)::after{
      inset-block-start: calc(var(--line-offset) * -1);
    }
}

@media (max-width:767px) {
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(2)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(3)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(4)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(5)::before,
  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(6)::before{
      inset-inline-start: calc(1em * -1);
    }


  .bm-feature-71-grid-ul > .bm-feature-71-card:nth-child(2)::after{
      inset-block-start: calc(var(--line-offset) * -1);
    }
}

/* CARD */

.bm-feature-71-card {
  transition: 0.5s ease;
}

.bm-feature-71-card:hover {
  background-color: var(--base-ultra-light);
}

/* Icon wrapper */

.bm-feature-71-card__icon-wrapper {
  transition: 0.5s ease;
}

.bm-feature-71-card:hover .bm-feature-71-card__icon-wrapper {
  background-color: var(--base);
  color: var(--text-light);
}

/* Button */
.bm-feature-71-card:hover .bm-feature-71-card__btn{
   /* Outline */
  --btn-custom-outline-color--hover: var(--text-light);

  --btn-custom-outline-background--hover: var(--base);
 	color: var(--btn-custom-outline-color--hover) !important;
  background-color: var(--btn-custom-outline-background--hover) !important;

}

.bm-feature-71-card__btn {
  /* Filled */
  --btn-custom-color: var(--text-light);
  --btn-custom-color--hover: var(--text-light);

  --btn-custom-background: var(--primary);
  --btn-custom-background--hover: var(--primary-light);

  --btn-custom-border-color: var(--primary);
  --btn-custom-border--hover: var(--primary-light);

   /* Outline */
  --btn-custom-outline-color: var(--text-dark);
  --btn-custom-outline-color--hover: var(--body-text-white);

  --btn-custom-outline-background: transparent;
  --btn-custom-outline-background--hover: transparent;

  --btn-custom-outline-border-color: var(--primary);
  --btn-custom-outline-border--hover: var(--primary-light);

   /* Style */
  --btn-border-radius: var(--radius-m);
  --btn-border-radius-hover: var(--radius-m);
  --btn-border-width: 1px;
  --btn-border-width-hover: 1px;
  --btn-shadow: none;
  --btn-transition: all 0.5s ease;
  --btn-outline-shadow: none;
  --btn-outline-border-width-hover: 1px;
  --btn-outline-border-width: 1px;
  --btn-shadow-hover: var(--box-shadow-xs);
  --btn-outline-border-radius: var(--radius-xs);
  --btn-outline-border-radius-hover: var(--radius-xs)  ;

	/* Sizes */
  --btn-small-font-size: var(--text-xs);
  --btn-small-block: 0.8em;
  --btn-small-inline: 1em;

  --btn-medium-font-size: var(--text-s);
  --btn-medium-block: 1.2em;
  --btn-medium-inline: 1.6em;

  --btn-large-font-size: var(--text-m);
  --btn-large-block: 1.2em;
  --btn-large-inline: 1.6em;

  --btn-x-large-font-size: var(--text-l);
  --btn-x-large-block: 1.2em;
  --btn-x-large-inline: 1.6em;


  /* Actual button styles using the variables */
  font-size: var(--btn-large-font-size);
 	color: var(--btn-custom-outline-color) !important;
  text-align: center;
  font-style: normal;
  line-height: 1;
  text-decoration: none;
  background-color: var(--btn-custom-outline-background) !important;
  border: var(--btn-border-width) solid var(--btn-custom-border-color);
  border-radius: var(--btn-border-radius) !important;
  box-shadow: var(--btn-shadow);
  transition: var(--btn-transition);
 	padding-block: var(--btn-small-block);
  padding-inline: var(--btn-medium-inline);
  position:relative;
  overflow:clip;
  isolation: isolate;
}

